#include <iostream>
#include <unordered_map>
#include <utility>
#include <tuple>

using namespace std;

long long compute(int n, int h, unordered_map<tuple<int, int>, long long>& cache) {
    auto key = make_tuple(n, h);
    if (cache.find(key) == cache.end()) {
        long long result;
        if (n == 0) {
            result = 1;
        } else if (h > 0) {
            long long sum = 0;
            for (int i = 0; i < n; ++i) {
                sum += compute(i, h - 1, cache) * compute(n - 1 - i, h - 1, cache);
            }
            result = sum;
        } else {
            result = 0;
        }
        cache[key] = result;
    }
    return cache[key];
}

int main() {
    int n, h;
    cin >> n >> h;
    unordered_map<tuple<int, int>, long long> cache;
    long long res1 = compute(n, n, cache);
    long long res2 = compute(n, max(0, h - 1), cache);
    cout << res1 - res2 << endl;
    return 0;
}

